 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 16:29:28', '13-04-2026 16:29:28', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 22, 2609, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_444640_bum_vce78c1c9.jpg', 1, 0, 4.02, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229773.html', '2026-04-14T07:05:54.887522');
