ncial', 'Full-time', '08-04-2026', '08-04-2026 13:26:56', '13-04-2026 18:07:42', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2350, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223465.html', '2026-04-14T07:05:54.887796');
