INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227752, 13357343, 'Chofer de Camión con Experiencia en Hidroelevador', 'SP2 GROUP SA', 'Chofer de Camión con Experiencia en Hidroelevador Resumen del PuestoBuscamos un Chofer de Camión responsable, dinámico y con buena presencia para unirse a nuestro equipo a tiempo completo. El candidato ideal poseerá experiencia en la conducción de hidroelevadores y un registro de conducir vigente.Responsabilidades Operar camiones y equipos de transporte de manera segura y eficiente. Manejar y operar hidroelevadores para la carga y descarga de materiales. Realizar inspecciones previas y posteriores al viaje del vehículo. Cumplir con todas las normativas de tránsito y seguridad vial. Mantener el vehículo limpio y en buen estado de funcionamiento. Colaborar con otros miembros del equipo para asegurar la eficiencia operativa.Requisitos Registro de conducir categoría E2 (o equivalente). Experiencia comprobable en la conducción de camiones. Experiencia específica en la operación de hidroelevadores. Capacidad para realizar tareas de forma responsable y autónoma. Habilidades de comunicación y trato interpersonal. Disponibilidad para trabajar a tiempo completo.', 0, 'José León Suárez, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 14:04:28', '13-04-2026 14:04:28', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 3, 109, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227752.html', '2026-04-14T07:05:54.888498');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223913, 13159697, 'Cloud System Administrator', 'Cybele Software', 'En Cybele Software estamos transformando la forma en que las personas acceden a sus espacios de trabajo digitales. Con Thinfinity® Workspace, hacemos posible que cualquiera utilice aplicaciones de Windows directamente desde el navegador, sin complicaciones. Más de 5000 clientes en todo el mundo confían en nosotros, y seguimos creciendo para ofrecer soluciones innovadoras. Estamos en la búsqueda de un Cloud System Administrator con experiencia en entornos virtuales, motivación por la tecnología y ganas de seguir creciendo junto a un equipo en expansión. En este rol, serás responsable de gestionar y optimizar nuestra infraestructura virtual, asegurando que todo funcione de manera eficiente, segura y sin interrupciones. Tus responsabilidades clave: Implementar y mantener infraestructura como código (IaC) usando Terraform. Administrar plataformas Cloud (OCI, Azure, AWS, GCP, Ionos), garantizando alto rendimiento y optimización de recursos. Gestionar entornos On-Premise con Hyper-V, VMware y/o Proxmox. Desarrollar y automatizar pipelines de CI/CD para integración y entrega continua. Garantizar la estabilidad y performance del producto a través de pruebas avanzadas y prácticas de automatización (Unit Tests, Pipeline Tests, Smoke Tests, Load & Performance Tests) Colaborar con equipos de desarrollo para optimizar flujos de trabajo y la calidad del software. Implementar medidas de seguridad y cumplimiento normativo en toda la infraestructura. Requisitos: +5 años de experiencia en administración de entornos virtuales o puestos similares. Conocimiento avanzado en virtualización (Hyper-V, VMware). Experiencia en DevOps: pipelines, CI/CD y scripting (PowerShell, Python o Bash). Experiencia en Terraform. Dominio de Cloud (preferentemente OCI y Azure). Conocimientos avanzados en redes y configuración de firewalls. Conocimiento avanzado en contenedores (Docker/Podman). Experiencia con Kubernetes o similares (deseable). Beneficios ¿Por qué sumarte a Cybele?En Cybele, las personas son el motor de todo lo que hacemos. Fomentamos un ambiente dinámico donde la autonomía, la innovación y el trabajo en equipo van de la mano. Formarás parte de un equipo que impulsa la excelencia técnica y el crecimiento continuo.Lo que ofrecemos: Revisión salarial para acompañar la inflación. Esquema híbrido: 2 días remotos y 3 días en la oficina (Belgrano, CABA). Estacionamiento gratuito. Cobertura médica con OSDE para vos y tu familia. Ajustes salariales por desempeño para reconocer tu crecimiento. Día libre en el mes de tu cumpleaños.️ Membresía Club La Nación Premium con descuentos exclusivos.Nuestro proceso de selecciónQueremos que nuestro proceso sea claro y enfocado en conocer tu potencial único. Estos son los pasos: Entrevista con RRHH: una charla para conocerte, contarte más sobre lo que hacemos y entender tu experiencia y motivaciones. Entrevista técnica: vas a conocer a nuestro equipo técnico, explorar desafíos del día a día y profundizar en tus conocimientos. Evaluación técnica: puede ser una prueba práctica o una conversación más profunda sobre tu experiencia. ¿Estas buscando dar el siguiente paso en tu carrera? ¡Postulate!', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '08-04-2026', '08-04-2026 16:08:13', '08-04-2026 16:08:13', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 19, 34, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13159697_bum_v85b6301c.jpg', 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223913.html', '2026-04-14T07:05:54.888717');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229240, 13330439, 'SAP S/4HANA Cloud Public Edition – FICO Consultant ( Mercado USA)', 'WE ARE REMOTERS', 'Find Bandit es una empresa especializada en conectar talento profesional de Latinoamérica con empresas internacionales, principalmente de Estados Unidos, que buscan sumar personas a sus equipos de forma remota.Trabajamos acompañando a los candidatos a lo largo de todo el proceso de selección, con una comunicación clara, cercana y transparente. Nuestro objetivo es que conozcas en profundidad cada oportunidad: el proyecto, el equipo, el tipo de trabajo y las expectativas, para que puedas evaluar si realmente se alinea con tu experiencia y tus objetivos profesionales.En Find Bandit creemos que una buena experiencia comienza con procesos honestos y bien comunicados. Por eso, buscamos generar vínculos de largo plazo, cuidando tanto a las personas como a las empresas con las que trabajamos. Nos interesa que cada incorporación sea una decisión consciente, sostenible y positiva para ambas partes.Si estás buscando un nuevo desafío remoto, trabajar con equipos internacionales y seguir creciendo profesionalmente, en Find Bandit te acompañamos para que encuentres una oportunidad que realmente haga match con vos. Los Consultores SAP S/4HANA Cloud Public Edition son responsables del ciclo completo de implementación del sistema SAP S/4HANA Cloud para nuestros clientes. Como Consultor Cloud, tendrás un rol clave en el diseño, configuración, pruebas y puesta en marcha del sistema, además de capacitar a los usuarios para maximizar el valor de la solución SAP.Responsabilidades Principales Liderar el diseño funcional, configuración e implementación de SAP S/4HANA Cloud Public Edition – FICO. Trabajar con usuarios de negocio, equipos financieros y áreas de IT para relevar requerimientos y traducirlos en soluciones SAP. Configurar procesos end‑to‑end de FICO: GL, AR, AP, Activos Fijos, Tesorería, Banking, Payment Management, Cost/Profit Center Accounting. Asegurar la integración entre FICO y módulos operativos (Ventas, Compras, Producción, Proyectos). Liderar pruebas funcionales, UAT y capacitaciones a usuarios finales. Participar en actividades de migración y conversión de datos. Colaborar en proyectos de transformación y migración a SAP S/4HANA (SAP B1 → S/4HPC, SAP ByD → S/4HPC). Elaborar especificaciones funcionales para desarrollos. Brindar soporte post‑go‑live y proponer mejoras continuas. Trabajar bajo metodología SAP Activate (Fit‑to‑Standard, Testing, Data Migration). Requisitos: RequisitosObligatorios +2 años de experiencia como Consultor SAP S/4HANA Cloud Public Edition – FICO. Experiencia práctica en implementaciones o migraciones end‑to‑end. Manejo de herramientas de Public Cloud: CBC, ALM, Signavio, Best Practices Explorer. Experiencia en FIT‑TO‑STANDARD. Experiencia en integración de FICO con LoBs operativos. Experiencia implementando Localización USA (US GAAP, impuestos y contabilidad). Inglés avanzado C2 (excluyente). Visa USA activa o elegibilidad para viajar a Estados Unidos. Disponibilidad para viajar hasta 30% del tiempo. Excelentes habilidades de comunicación, análisis y presentación. Capacidad para definir requerimientos funcionales y elaborar especificaciones detalladas. Dominio de MS Office (Excel, Word, PowerPoint). Deseable Título universitario en Contabilidad, Finanzas, Negocios o IT. +8 años de experiencia en soluciones ERP. Certificación SAP S/4HANA Cloud Public Edition – Finance. Conocimientos en SAP FSCM. Residencia en LATAM. Beneficios Trabajo remoto con 30% de viajes en USA puntuales a clientes según proyecto. Pago en USD a través de la plataforma Ontop. Feriados según país de residencia. Vacaciones al cumplir 1 año de servicio. Participación en proyectos internacionales de alto impacto. Entorno profesional, colaborativo y multicultural. Oportunidades de crecimiento.', 0, 'Buenos Aires', 'Remoto', 'Full-time', '13-04-2026', '13-04-2026 13:16:59', '13-04-2026 13:16:59', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 19, 34, 1, NULL, 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229240.html', '2026-04-14T07:05:54.888921');
