INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118133772, 10086776, 'Asesores de cobranzas fideicomiso', 'Proaction Services S.A.', 'En Proaction Services queremos sumar nuevos talentos a nuestro equipo de trabajo. Nos encontramos en la búsqueda de Asesores de Cobranzas, con ganas de crecer y desarrollarse en un entorno dinámico y profesional.¿Sos uno de los MEJORES COBRADORES del mercado?¡Te estamos buscando!Carteras de alta recuperabilidad, con asignacion constante.Pagamos hasta 9% de comision (objetivos alcanzables)Perfil que buscamos: Experiencia minima 2 años en gestion de carteras de fideicomiso. Experiencia previa en call center (Excluyente) Secundario completo. Residencia en Buenos Aires.Beneficios: 100% remoto. Esquema especial de comisiones drante los primeros 2 meses de inicio. Contratación efectiva bajo el Convenio de Comercio. Reales oportunidades de crecimiento y desarrollo profesional.', 0, 'Capital Federal, Buenos Aires', 'Remoto', 'Part-time', '13-04-2026', '13-04-2026 14:15:48', '13-04-2026 14:15:48', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 20, 0, 25, 106, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10086776_bum_v45df1d87.jpg', 0, 0, 3.0, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118133772.html', '2026-04-14T07:05:54.889264');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225461, 379670, 'Operadores/as Telefónicos de Cobranzas', 'GST', 'En Grupo ST creemos que las ganas de crecer merecen convertirse en realidad. Por eso, desde hace más de 20 años acompañamos a personas y empresas en todo el país, impulsando su desarrollo con soluciones concretas en crédito, inversión, seguros y más. Somos un ecosistema de compañías especializadas que comparten una misma convicción: que el crecimiento de Argentina empieza por quienes se animan. Hoy, más de personas trabajamos juntas para transformar oportunidades en logros reales. ¿Y si tu próximo paso es desde adentro? En Grupo ST estamos buscando Operadores/as de Cobranzas con vocación por acompañar a nuestros clientes en las primeras etapas de su mora, ayudándolos a reencauzar sus compromisos y mantener su salud financiera . Tu misión será contactar a clientes con deudas recién vencidas, comprender su situación y ofrecer alternativas de pago ágiles y sosteniblesBrindarás una atención telefónica cercana y profesional , orientada a la prevención y recuperación temprana, contribuyendo a que cada cliente encuentre una solución adaptada a su realidad. Vas a registrar las gestiones en el sistema, realizar seguimientos y aplicar estrategias de negociación acordes a cada perfil, siempre dentro de un marco ético y colaborativo ️. ¿Te motiva generar un impacto positivo desde la escucha y la empatía? Si querés ser parte de un equipo que combina compromiso, profesionalismo y resultados, ¡postulate y sumate a Grupo ST! Requisitos: Secundario completo (excluyente). Manejo de herramientas informáticas: Word y Excel. Se valorará contar con estudios en curso en Administración, Contabilidad, Derecho, Comunicación, Psicología u otras carreras afines.️ Experiencia en el uso de sistemas de gestión o CRM (deseable).', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Part-time', '14-04-2026', '14-04-2026 05:02:31', '14-04-2026 05:02:31', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 25, 110, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_379670_bum_vecbeef67.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225461.html', '2026-04-14T07:05:54.889361');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229102, NULL, 'Analista de Cobranzas (Cuentas a Cobrar)', 'Confidencial', 'Analista de Cobranzas (Cuentas a Cobrar) Nos encontramos en la búsqueda de un/a Analista de Cobranzas (Cuentas a Cobrar) para sumarse al equipo de Administración y Finanzas de una compañía en crecimiento.La posición tiene como objetivo gestionar de manera eficiente el circuito de cobranzas, asegurando el seguimiento de cuentas corrientes, la correcta registración y la disponibilidad de información confiable para la toma de decisiones financieras.Principales responsabilidades: Gestionar activamente la cobranza, anticipando vencimientos y realizando seguimiento a clientes Conciliar de manera permanente las cuentas corrientes, manteniendo información actualizada y ordenada Interactuar con el área comercial ante facturas en disputa, dando seguimiento hasta su resolución Registrar recibos en el sistema de gestión, asegurando la correcta imputación de pagos Elaborar reportes periódicos sobre estado de cuentas, saldos vencidos y gestión de cobranzas Analizar desvíos, identificar causas y proponer ajustes Confeccionar proyecciones de cobranzas para el armado del cash flow Generar indicadores y métricas de eficiencia en la gestión de cobranzasRequisitos: Experiencia de 2 a 3 años en posiciones similares o en áreas administrativas con exposición a cuentas corrientes Formación en Administración de Empresas o afines (no excluyente) Manejo de Excel y sistemas de gestión Experiencia en conciliaciones y seguimiento de cuentasBuscamos perfiles que: Sean organizados, analíticos y con fuerte orientación al detalle Tengan buen manejo de relaciones interpersonales, especialmente en el trato con clientes Se adapten a entornos dinámicos y puedan manejar múltiples temas en simultáneo Sean proactivos, con foco en la resolución de problemas Se involucren con el equipo y aporten valor más allá de sus tareas específicasSe trata de una posición clave dentro del circuito financiero, en un contexto de PyME en crecimiento, donde se valoran perfiles con actitud, flexibilidad y ganas de sumar al desarrollo del negocio.', 1, 'Vicente López, Buenos Aires', 'Híbrido', 'Full-time', '13-04-2026', '13-04-2026 12:33:49', '13-04-2026 16:10:24', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229102.html', '2026-04-14T07:05:54.889453');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221365, 466770, 'Analista de Cobranzas /Zona Martínez', 'BAYTON', 'Para nuestro cliente dedicado a la distribución de materiales eléctricos de uso industrial ubicada en la Zona de Martínez, seleccionaremos un/a Analista de Cobranzas para sumarse al equipo.Misión del Puesto:Realizar las cobranzas de clientes, seguimiento de las cuentas corrientes y detección de morosidad, confección de ND y NC por diferencia de tipo de cambio.Eventualmente, colaborar con sector facturación.Deberá interactuar con los portales de los clientes por gestiones de facturación y pagos.Requisitos:Experiencia en sectores similares con buen manejo de Sistemas Contables y de Paquete Office.Conocimiento en Imputaciones Contables, Retenciones Impositivas (Excluyente).Facturación (confección de FC, ND y NC).Competencias Requeridas:Buenas relaciones interpersonales.Buen nivel de comunicación (oral - escrita).Compromiso laboral y dedicación para alcanzar los objetivos esperados.Jornada Laboral:Lunes a Viernes (presencial) de 8:00 a 17:00 Hs.Disponibilidad inmediata para incorporarse.Aguardamos tu postulación, envianos tu CV actualizado.', 0, 'Martínez, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 12:47:29', '13-04-2026 09:22:42', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 1, 2592, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_466770_bum_v7cd0e054.jpg', 1, 0, 3.92, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221365.html', '2026-04-14T07:05:54.889522');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227521, 13475334, 'Vendedor con manejo de caja y cobranzas - Wilde', 'Nexoar', 'Vendedor de Salón y Operador de Caja / RapipagoObjetivo de la posición: Buscamos una persona proactiva, responsable y con marcada vocación de servicio para sumarse a nuestro equipo de ventas. El objetivo principal es brindar una excelente atención al cliente, garantizando la correcta gestión de cobros y el mantenimiento óptimo del salón de ventas.Principales tareas y responsabilidades: Atención al Cliente: Recibir y asesorar a los clientes de forma personalizada para concretar ventas y resolver consultas. Gestión de Caja y Rapipago: Realizar el cobro de productos y servicios de Rapipago, manejo de efectivo, tarjetas de crédito/débito y rendición diaria de caja. Gestión de Stock: Colaboración en la recepción de mercadería, realización de inventarios periódicos y reposición constante de productos en góndola. Mantenimiento del Salón: Etiquetado de precios, organización de productos, armado y actualización de vidrieras para potenciar las ventas. Orden General: Asegurar la limpieza y el orden constante tanto del sector de caja como del salón comercial.Requisitos y dinámica de trabajo: Experiencia: Previa en manejo de caja y/o puestos de ventas. Habilidades: Capacidad para trabajar de forma organizada y bajo objetivos. Jornada Laboral: Horario Full-time de lunes a sábado (48 horas semanales). Ubicación: Trabajo presencial en nuestra sucursal de Wilde.', 0, 'avellaneda, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 17:44:32', '13-04-2026 13:25:22', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13475334_bum_v31988285.jpg', 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227521.html', '2026-04-14T07:05:54.889667');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229184, 13511163, 'Ayudante de Cocina', 'Maria Maria', 'Ayudante de Cocina Resumen del Puesto Buscamos un Ayudante de Cocina proactivo y con gran disposición para integrarse a nuestro equipo de trabajo. El candidato ideal deberá tener experiencia en la preparación de alimentos y un fuerte compromiso con la calidad y la higiene. Responsabilidades Colaborar en la elaboración de diversos productos culinarios, especialmente en el área de comida salada. Asistir en el manejo de equipos de cocina y cocción. Realizar el control de inventario de insumos y materias primas. Participar en la elaboración de listados de materiales necesarios para la producción. Mantener el orden, la limpieza y la higiene en todas las áreas de trabajo de la cocina. Requisitos Experiencia previa en puestos similares en cocinas o establecimientos de alimentos. Conocimientos básicos en técnicas de preparación de alimentos. Capacidad para seguir instrucciones y trabajar bajo presión. Habilidad para el control de stock y la gestión de inventarios. Actitud proactiva, responsable y con atención al detalle. Disponibilidad para trabajar en equipo y mantener un ambiente de trabajo ordenado.', 0, 'Rosario, Santa Fe', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 12:56:34', '13-04-2026 12:56:34', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2350, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229184.html', '2026-04-14T07:05:54.889822');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229106, 13466918, 'Ayudante de Cocina y Producción', 'El perla', 'Ayudante de Cocina y Producción Resumen del Puesto Estamos en la búsqueda de un Ayudante de Cocina y Producción dinámico y proactivo para integrarse a nuestro equipo. El rol implica la preparación de alimentos y el apoyo en diversas tareas de producción, asegurando la calidad y eficiencia en la operativa diaria. Responsabilidades Preparación de ingredientes para la elaboración de sándwiches, hamburguesas y otros productos. Producción de ensaladas, cortes de fiambres y otros componentes. Armado de sándwiches y otros productos según demanda. Colaboración en tareas de cocina, incluyendo el uso de freidora cuando sea necesario. Mantenimiento del orden y la limpieza en el área de trabajo. Apoyo en la gestión de inventario de insumos. Requisitos Experiencia previa en puestos similares en gastronomía. Conocimiento en preparación de alimentos y manejo de utensilios de cocina. Capacidad para trabajar en diferentes turnos (mañana/noche). Habilidad para trabajar bajo presión y en un entorno de ritmo rápido. Actitud positiva y disposición para aprender. Buenas habilidades de organización y atención al detalle.', 0, 'Manuel B. Gonnet, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 12:34:26', '13-04-2026 12:34:26', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2350, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229106.html', '2026-04-14T07:05:54.889913');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118220531, 10183189, 'COCINERO', 'Liserar S.A', 'Somos una empresa que brinda servicios gastronómicos para industrias e instituciones desde hace más de 28 años, garantizando atención puntual y personalizada a cada cliente, buscando incorporar permanentemente avances tecnológicos a los procesos de producción, consiguiendo así costos y calidades muy competitivas.Actualmente brindamos servicios en Capital Federal, Gran Buenos Aires y las provincias de Santa Cruz, Santa Fe, La Rioja y Rio Negro con un equipo de profesionales destacados en el rubro.Las normas ISO 9001, 14001 y 45001 respaldan cada uno de nuestros servicios, sin dejar de apuntar a un servicio casero que haga del momento de la comida un tiempo de descanso y recuperación ¡Estamos buscando Cocinero/a! con experiencia en grandes volumenes de producciónSumate a nuestro equipoPuesto: Cocinero/a con experiencia en gastronomía industrialZona: CABATareas principales:Elaboración de comidas según recetasManejo de grandes volúmenes de producciónControl de calidad, tiempos y temperaturasOrden, limpieza e higiene del sectorCumplimiento de normas de seguridad alimentariaRequisitos:Experiencia comprobable en cocina industrialConocimiento en BPM e inocuidad alimentariaDisponibilidad full timeCarnet de manipulación de alimentos (deseable)¿Te interesa o conocés a alguien?WhatsApp: Requisitos:', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 05:03:14', '09-04-2026 05:03:14', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2350, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220531.html', '2026-04-14T07:05:54.889992');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229843, 10107503, 'Ejecutivo comercial', 'Drogueria del Sud S.A', 'En el Holding del Sud, cada una de nuestras empresas trabaja en perfecta sinergia para generar un impacto positivo y fundamental en el sistema de salud argentino. Nos enfocamos en garantizar que cada engranaje funcione con innovación, tecnología y excelencia operativa, ofreciendo un servicio único a nuestros clientes. Nuestros principales activos son Droguería del Sud, Laboratorios Temis Lostaló y Flexilog. Droguería del Sud es la distribuidora líder de productos farmacéuticos en Argentina, con 75 años de trayectoria. Abastecemos integralmente a pequeñas y grandes farmacias, centros de salud, hospitales y clínicas públicas y privadas, ministerios y obras sociales asegurando una logística eficiente que llega a cada rincón del país. Laboratorios Temis Lostaló se destaca, desde 1968, por su excelencia farmacéutica. Con productos innovadores como Total Magnesiano y Fosfovita, además de las líneas medicinales y de diagnóstico, demostramos nuestro compromiso constante con la salud. Flexilog responde a las demandas del mercado con soluciones logísticas a medida, combinando eficiencia operativa y alianzas estratégicas con proveedores nacionales e internacionales para garantizar un servicio de alto rendimiento. Si te interesa formar parte de un equipo que contribuye al bienestar del sistema de salud argentino, cargá tu CV o aplicá a las vacantes disponibles. ¡Te invitamos a sumar talento! En esta oportunidad, nos encontramos en la búsqueda de un/a Ejecutivo comercial para el área de Operaciones.El objetivo de la posición será:Desarrollar y ampliar la cartera comercial de Flexilog, generando nuevos negocios y fortaleciendo vínculos con clientes mediante la venta de soluciones logísticas integrales, con foco en la expansión de servicios y el modelo de puntos de terceros como diferencial.Algunas de sus responsabilidades serán: Identificar, contactar y desarrollar potenciales clientes de distintas industrias con necesidad de soluciones logísticas Relevar necesidades, comprender la operación del cliente y armar propuestas comerciales alineadas a los servicios de Flexilog. Impulsar comercialmente la incorporación y uso de puntos de terceros como alternativa de entrega y retiro, integrando esta propuesta dentro de la oferta comercial de Flexilog. Trabajar junto a Operaciones, Administración, Sistemas, Customer Service y otras áreas para validar factibilidad, costos, alcance y condiciones del servicio. Mantener contacto con clientes activos, detectar nuevas necesidades, gestionar desvíos y generar oportunidades de crecimiento dentro de la cuenta. Elaborar reportes de pipeline, avances de gestión, forecast, estado de cotizaciones y resultados comerciales. Analizar tendencias, competencia, oportunidades logísticas y necesidades del mercado. Proponer acciones, segmentos objetivo, mejoras en pricing, enfoque comercial y nuevos desarrollos de servicio. Requisitos: Orientamos la búsqueda a estudiantes avanzados o graduados de las carreras de Administración de Empresas, Comercialización, Logística, Ingeniería o afines con 4 años en posiciones similares.Competencias requeridas: Negociación Comunicación asertiva Capacidad analítica Excel avanzado Paquete Office avanzado SAP deseable Manejo de herramientas de seguimiento comercialConocimientos requeridos:Procesos logísticos y comercialesDistribución, Warehousing, Ecommerce, última milla y puntos de retiro.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '13-04-2026', '13-04-2026 16:56:04', '13-04-2026 16:56:04', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 3, 29, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10107503_bum_vbbda93ba.jpg', 1, 0, 3.2, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229843.html', '2026-04-14T07:05:54.890161');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229806, NULL, 'Coordinador Comercial', 'Confidencial', 'Importante compañía aseguradora, líder en el mercado, busca incorporar un Coordinador para el sector Comercial. Objetivo del puesto: Coordinar el área comercial actuando como referente operativo y soporte del Jefe del área, articulando y conciliando la interacción entre clientes, equipo comercial y áreas internas, fortaleciendo el trabajo colaborativo y la relación con los clientes, y asegurando el cumplimiento de los objetivos comerciales mediante la gestión, interacción y seguimiento. Sus principales responsabilidades serán: Gestión de equipos de trabajo. Coordinación operativa del sector. Atención al asegurado. Acciones de fidelización. Gestión y nexo entre Oficinas y áreas de la Mutual. Atención a colaboradores externos. Manejo de página web institucional y sitio de autogestión del asegurado. Manejo de reportes, tableros, indicadores para la mejora continua del área. Gestión interna (entre las distintas áreas de la Mutual). Motivar a los miembros del equipo a mejorar su trabajo. Requisitos: Disponibilidad para viajar Manejo Paquete Office (Excel intermedio/avanzado) Experiencia en Gestión de equipo y coordinación operativa Habilidades de negociación Perfil analítico y comercial Capacidad de organización Capacidad de Resolución de problemas Se valorará especialmente Contar con formación terciaria o universitaria en Comercialización, Administración y/o Seguros, así como también poseer experiencia trabajando con Power BI y tableros de comando. Jornada Jornada laboral de Lunes a Viernes de 9:45hs a 17:15hs Modalidad hibrida Zona Abasto', 1, 'Buenos Aires, Buenos Aires', 'Híbrido', 'Full-time', '13-04-2026', '13-04-2026 16:41:22', '13-04-2026 16:41:22', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, NULL, NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229806.html', '2026-04-14T07:05:54.890302');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229580, 13141399, 'Asesor Comercial', 'Ecoexist Bolsas Ecológicas', 'Color SublimeSomos una empresa joven en expansión que diseña y fabrica maquinaria e insumos para sublimación/estampado, con presencia en Argentina, Chile y México. Nuestra filosofía se basa en aportar valor, brindando asesoramiento personalizado, rápido. Trabajamos con procesos claros, métricas visibles y foco en performance.¿Qué buscamos?Nos orientamos a la búsqueda de una persona con un marcado perfil comercial, cerradora de ventas y empática.Es importante que cuente con experiencia comprobable en ventas on-line o telemarketing y manejo de WhatsApp Business / CRM (Excluyente). Es deseable que tenga conocimientos de plataformas e-commerce, Ej: Mercado Libre, Tienda Nube, Shopify, Comercial, y sería un plus venir del mundo gráfico.Tu misiónConvertir leads entrantes en ventas con un estándar alto de atención: velocidad, diagnóstico, propuesta clara, manejo de objeciones y seguimiento, usando el CRM como herramienta central.¿Cuáles son las responsabilidades del puesto?● Gestionar leads entrantes (no venta en frío) con foco en conversión y cierre.● Mantener el pipeline en CRM impecable: etapas, notas, tareas, etiquetas, cadencias de seguimiento.● Seguimiento de las ventas con las áreas de Logística y Administración.● Cumplir objetivos de performance (respuesta, contacto efectivo, avance de etapa, conversiones).● Reportar y mejorar métricas semanalmente.Nuestra oficina se encuentra en Saavedra.Requisitos● Experiencia comprobable en ventas (ideal consultiva / ticket medio-alto / alto volumen).● CRM: usaste pipeline, tareas y seguimiento sistemático (HubSpot, Kommo, Salesforce u otro).● Disciplina y cadencia● Orientación a resultados● Excelente comunicación y manejo de objeciones.¿Qué ofrecemos?● Lunes a viernes de 9 a 18hs. Sábados de 10 a 14hs.● Esquema fijo + variable por performance.● Modalidad híbrida● 2 semanas de vacaciones + 1 semana plus● Coaching comercial, procesos claros y posibilidad real de crecimiento para quien rinde.Si te interesa sumarte a un equipo dinámico con muy buen clima laboral y en constante crecimiento, ¡esperamos tu postulación!', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '13-04-2026', '13-04-2026 15:01:30', '13-04-2026 15:01:30', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, 1, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229580.html', '2026-04-14T07:05:54.890476');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227355, 980230, 'Ejecutivo comercial', 'External Market', '📢 Ejecutivo/a de Cuentas – Ventas ConsultivasNos encontramos en la búsqueda de un/a Ejecutivo/a de Cuentas para sumarse a nuestro equipo comercial, con foco en el desarrollo de nuevos negocios y gestión de clientes.🧭 ¿Cuál será tu misión?Llevar adelante la comercialización de nuestros productos y servicios, cumpliendo con los objetivos comerciales definidos y generando relaciones de valor con los clientes.💼 Principales responsabilidades: Desarrollo de nuevas oportunidades de negocio. Gestión integral del proceso comercial (detección de necesidades, propuesta y cierre). Asesoramiento consultivo a clientes. Seguimiento de cartera y fidelización. Uso de herramientas CRM para la gestión comercial. Trabajo colaborativo con otras áreas.🔍 ¿Qué buscamos? Experiencia mínima de 2 años en posiciones comerciales. Perfil con fuerte orientación a resultados y vocación de servicio. Buen nivel de comunicación y presencia profesional. Capacidad de negociación y autonomía en la gestión. Manejo de herramientas informáticas (CRM, paquete Office). Valoraremos experiencia en venta de soluciones tecnológicas o servicios.💡 Competencias clave: Proactividad y compromiso. Adaptabilidad a distintos escenarios. Creatividad para generar oportunidades comerciales. Interés por el desarrollo profesional.📍 Modalidad de trabajo: Esquema híbrido. Jornada: lunes a viernes de 8:30 a 17:30 hs.💰 ¿Qué ofrecemos? Sueldo básico + comisiones sin tope. Bono por cumplimiento de objetivos. Viáticos. Capacitaciones constantes. Gift card.', 0, 'Munro, Buenos Aires', 'Híbrido', 'Full-time', '10-04-2026', '10-04-2026 16:35:50', '13-04-2026 10:57:31', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227355.html', '2026-04-14T07:05:54.890629');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224840, 641690, 'Activador comercial', 'CROMOSOL S.A.', 'Cromosol es la empresa distribuidora de autopartes número uno en Argentina. Con 80 años de trayectoria, la firma ha logrado consolidarse como líder en el mercado, respondiendo con compromiso e innovación a la evolución y exigencias del sector. La estrategia de Cromosol está orientada a la satisfacción de sus clientes, por ello, durante cuatro generaciones ha trabajado de forma constante en la mejora de su atención, calidad de su servicio y variedad de su catálogo de productos. Actualmente, Cromosol cuenta con un depósito modelo que le permite comercializar más de 24.000 artículos a 3.500 clientes. Además, gracias a su amplia red de representantes oficiales, tiene cobertura en todo el país. En Cromosol estamos expandiendo nuestra célula de recuperación y captación de clientes, y buscamos incorporar perfiles comerciales con mirada analítica, foco en el cliente y orientación a resultados. Esta posición no está pensada como un rol de call center tradicional.Buscamos personas capaces de generar conversaciones de valor, entender el contexto del cliente y detectar oportunidades reales de negocio, trabajando en conjunto con un equipo comercial a nivel nacional. Responsabilidades- Contactar clientes inactivos y prospectos con un enfoque consultivo- Analizar el historial y contexto comercial de cada cuenta- Calificar oportunidades y coordinar visitas con vendedores de zona- Gestionar seguimiento de leads y construir relaciones comerciales- Registrar información y asegurar trazabilidad en el proceso Condiciones- Modalidad presencial- Jornada full time (lunes a viernes)- Esquema de compensación: fijo + variable por resultados Requisitos: Perfil buscado- Experiencia en ventas telefónicas (call center), desarrollo comercial o atención al cliente- Fuerte capacidad de comunicación y escucha activa- Criterio comercial y autonomía en la gestión- Organización y disciplina en el seguimiento de oportunidades- Orientación a resultados con foco en calidad de leads (no volumen vacío) Valor diferencial- Experiencia en entornos B2B- Manejo de CRM o herramientas de gestión comercial- Capacidad de trabajar con métricas y objetivos Beneficios Servicio de viandas con descuento del 50% Prepaga con valor coorporativo Snacks', 0, 'Tortuguitas, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 10:54:48', '09-04-2026 10:54:48', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, NULL, 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224840.html', '2026-04-14T07:05:54.890741');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118228894, NULL, 'Analista en Comercio Exterior', 'Confidencial', 'Seguimiento integral de todo el circuito de importación: Comunicación con Proveedores , Revisión de documentos, Coordinación de Transporte Internacional , Pago de gastos a agencias Locales , Transferencias al Exterior , Retiro de contenedores de puerto, Costeo de operaciones. Destinaciones: TRM / IC / IT. Seguimiento integral de todo el circuito de exportación: Comunicación con Clientes , Emisión documentos, Coordinación de Transporte Internacional, Pagos Locales, Ordenes de Pago del exterior, Costeo de Operaciones.', 1, 'La Plata, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 11:24:55', '13-04-2026 11:28:11', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 2, 100, 1, NULL, NULL, NULL, NULL, 2018, 'Conecta_AR_VE', 'bumeran', 'destacado', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118228894.html', '2026-04-14T07:05:54.890816');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221435, 613480, 'Analista de Comercio Exterior', 'X-28 Alarmas', 'Somos una empresa líder en seguridad electrónica que previene, protege y acompaña con soluciones integradoras tecnológicas que brindan una experiencia de calidad a nuestros clientes para hacer de este mundo un lugar más seguro.Contamos con 4 unidades de negocios: servicio de monitoreo profesional, alarmas vehiculares, alarmas residenciales y cámaras de seguridad. En cada una de ellas trabajamos para satisfacer las necesidades del mercado y transformar los deseos de nuestros clientes en una realidad.Trabajamos fuertemente con nuestro Departamento de Equidad e Inclusión para asegurar un lugar de trabajo seguro, ameno, saludable, honesto y justo. Un lugar de trabajo tranquilo, donde todos podamos desarrollarnos personal y profesionalmente. ¡Sumate a nuestro equipo! Nos encontramos en la búsqueda de un/a Analista de Comercio Exterior para nuestro equipo de Supply Chain. Buscamos una persona analítica, organizada y detallista, con foco en resultados, buena comunicación y capacidad de negociación.Funciones del puesto: Gestionar y negociar con proveedores los pedidos de productos, insumos y/o recursos surgidos del cronograma de compras. Realizar transferencias bancarias y FIDEIMPO según legislación vigente BCRA. Gestionar y controlar la documentación de importaciones/exportaciones. Coordinar con agentes de carga y despachantes. Gestionar intervenciones ante organismos regulatorios (Seguridad Eléctrica, pilas) Mantener actualizadas las planillas de seguimiento y brindar soporte administrativo al área.Jornada: Full time, lunes a viernes de 9 a 18 hs. Modalidad presencial. Lugar: Mataderos, CABA.Contrato a tiempo indeterminado Requisitos: Orientamos la búsqueda a estudiantes avanzados o egresado de terciario o carreras universitarias en Comercio Exterior, Comercio Internacional o carreras afines (Excluyente). Experiencia laboral previa no menor a 1 año en posiciones similares (Excluyente). Herramientas informáticas: Microsoft Office y Google Workspace (Nivel intermedio Excluyente). Idioma: Dominio de Inglés (Nivel avanzado Excluyente). Beneficios Día de cumpleaños‍Home office Incentivo anual por desempeño‍‍‍ Licencias extendidas y reintegros por guarderíaAlarma vehicular y servicio de monitoreo gratis para el colaboradorDescuento en línea celular‍️Descuentos en Sport ClubPosibilidades de crecimiento y desarrollo profesional', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 11:07:30', '13-04-2026 16:29:46', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 2, 100, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_613480_bum_v59966ae5.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221435.html', '2026-04-14T07:05:54.890925');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225693, 13085275, 'Analista Administrativo de Comercio Exterior', 'MODUM Consultora', 'Furi Trading, empresa del rubro textil con operación internacional, se encuentra en la búsqueda de un/a Analista Administrativo de Comercio Exterior para sumarse a su equipo.Furi Trading es una empresa trader dedicada al desarrollo de colecciones y comercialización de producto terminado para mercados internacionales, con producción en China y una dinámica de negocio ágil, comercial y global.👉 Importante: no se trata de un rol técnico especializado en comercio exterior, sino de una posición con foco principalmente administrativo, que requiere conocimiento general de documentación y procesos de comex. ¿Cuál es el foco del rol?La posición está orientada al seguimiento administrativo y documental de las operaciones, asegurando orden, control y coordinación.Algunas de sus responsabilidades serán: Armado, revisión y control de documentación (BL, packing list, invoices, etc.) Control y validación de facturas y documentación de embarques Seguimiento administrativo de operaciones logísticas Interacción con proveedores, clientes y despachantes Gestión de cuentas corrientes Organización y control de información comercial y logística Soporte administrativo general al negocio Perfil que buscamos Experiencia en posiciones administrativas vinculadas a comercio exterior Conocimiento general de documentación internacional (no excluyente experiencia técnica profunda) Buen manejo de Excel Nivel de inglés intermedio/avanzado Perfil organizado, resolutivo y con capacidad de seguimiento Condiciones Ubicación: Flores (CABA) Modalidad híbrida: 3 días presencial + 2 días home office Horario: lunes a viernes de 9 a 18 hs Modalidad de contratación: Monotributo💬 Si estás buscando una posición administrativa con exposición al comercio internacional, esta puede ser una muy buena oportunidad.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:03:28', '11-04-2026 08:37:30', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 2, 101, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13085275_bum_vdc0f5aca.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225693.html', '2026-04-14T07:05:54.891048');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118072200, 987530, 'Administrativo/a de Comercio Exterior / Administración Jr.', 'Importante Empresa de Calzado e Indumentaria', 'Responsabilidades:- Registrar facturas nacionales y del exterior.- Control diario de carga de comprobantes.- Manejo básico de documentación de comercio exterior.- Cierre y control de legajos de importación.- Seguimiento de facturas pendientes.- Gestión de planillas en Excel.- Tareas administrativas generales.Requisitos:- Estudiante o graduado/a de carreras afines.- 0 a 2 años de experiencia.- Conocimientos básicos de comercio exterior.- Excel intermedio.- Perfil ordenado, dinámico y resolutivo.Competencias:- Técnicas: Documentación Comex, registro administrativo, Excel, gestión documental.- Conductuales: Organización, atención al detalle, proactividad, comunicación, actitud positiva.Modalidad: Híbrida 4x1 (home office un día por semana)Beneficios:Obra Social, descuentos en productos, día de cumpleaños', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 08:34:20', '13-04-2026 08:34:38', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 2, 101, 1, NULL, 1, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118072200.html', '2026-04-14T07:05:54.891122');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118228410, 1476590, 'Analista de Comercio Exterior (San Martín)', 'Zivot Consultora en RH', 'Empresa Metalúrgica ubicada en San Martín incorpora un Analista de Comercio Exterior con una experiencia mínima de 5 años en posiciones similares en industrias (excluyente).Tareas Principales- Contacto y desarrollo de proveedores en el exterior.- Gestionar negociaciones y costos.- Evaluar, negociar y establecer relaciones con forwarders y despachantes aduaneros.- Manejo de importaciones, documentación, trámites aduaneros y logística internacional.- Activación de compras y/o servicios.Requisitos- Licenciado/a en Comercio Exterior o carreras afines.- Manejo avanzando de ERP en gestión de importaciones.- Conocimientos de costos.- Experiencia en industrias.- Inglés avanzado.- Residir Zona Norte del Gran Buenos Aires.Se ofrece remuneración acorde, bono anual, prepaga y comedor en planta.', 0, 'San Martin, Buenos Aires', 'Presencial', 'Full-time', '12-04-2026', '12-04-2026 11:32:09', '12-04-2026 11:32:09', '2026-04-12', NULL, NULL, '2026-04-12T00:00:00-03:00', NULL, NULL, 1, 0, 2, 100, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/1/4/7/6/5/9/0/logoMainPic_1476590.jpg', 0, 0, 4.85, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118228410.html', '2026-04-14T07:05:54.891189');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227469, 13343257, 'Analista SR. / Responsable de Comercio Exterior - Empresa industria Calzado', 'GRUPO Homini', 'Desde GRUPO Homini nos encontramos en búsqueda de un/a Analista SR. o Responsable de Comercio Exteriorpara incorporarse a una importante compañía ubicada en Parque Patricios, CABA.Modalidad de trabajo: 4 días presenciales y 1 día home office Horario: lunes a viernes de 08:00 a 17:00 hs¿Qué desafíos tendrá la posición? Coordinar y realizar el seguimiento integral de operaciones de comercio exterior. Gestionar y controlar documentación vinculada a importaciones y exportaciones. Mantener contacto operativo con despachantes de aduana, forwarders y clientes del exterior. Realizar el seguimiento de embarques, arribos, salidas, vencimientos y cumplimiento normativo. Controlar facturación de proveedores del área. Supervisar liberaciones para retiro y devolución de contenedores. Mantener registros actualizados y velar por el correcto cumplimiento de los procesos.¿Qué perfil buscamos? Personas con formación en Comercio Exterior, Administración, Economía o carreras afines. Experiencia mínima de 5 años en posiciones similares. Se valorará experiencia en rubros textil o calzado. Residencia en zonas cercanas a Parque Patricios o con fácil acceso.Competencias valoradas Perfil analítico, dinámico y orientado a resultados. Proactividad y capacidad de organización. Buen manejo de relaciones interpersonales. Capacidad de toma de decisiones y seguimiento operativo.Se ofrece Posición con proyección y posibilidades de desarrollo. Esquema de trabajo híbrido. Remuneración acorde a la posición.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '10-04-2026', '10-04-2026 17:22:49', '10-04-2026 17:22:49', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 2, 100, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13343257_bum_vec3246db.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227469.html', '2026-04-14T07:05:54.891270');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118228014, 13168089, 'Promotor de Ventas (Comisión)', 'SISCORP', 'Promotor de Ventas (Comisión) Resumen del Puesto Estamos en la búsqueda de Promotores de Ventas con un fuerte enfoque en la consecución de objetivos y una mentalidad orientada a resultados. El candidato ideal poseerá excelentes habilidades de comunicación y persuasión, con la capacidad de generar interés y cerrar acuerdos de manera efectiva. Este rol se basa en un esquema de comisión, ofreciendo un potencial de ingresos atractivo para aquellos con un alto desempeño. Responsabilidades Presentar y demostrar productos o servicios a clientes potenciales. Identificar y desarrollar nuevas oportunidades de negocio. Gestionar el ciclo completo de ventas, desde el contacto inicial hasta el cierre. Cumplir y superar los objetivos de ventas establecidos. Mantener relaciones sólidas con los clientes. Proporcionar retroalimentación sobre las necesidades del mercado. Requisitos Experiencia previa en ventas, preferiblemente en roles orientados a la comisión. Habilidades excepcionales de comunicación, negociación y cierre. Proactividad y automotivación para alcanzar metas. Capacidad para trabajar de forma autónoma y gestionar el tiempo eficientemente. Orientación al cliente y enfoque en la satisfacción. Disponibilidad para trabajar bajo un esquema de comisión.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 23:48:18', '11-04-2026 09:37:40', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13168089_bum_v968a958f.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118228014.html', '2026-04-14T07:05:54.891344');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179460, 679187, 'Preventista a Comisión', 'PALETONIA', 'Preventista a ComisiónResumen del PuestoEstamos en la búsqueda de un Preventista a Comisión proactivo y con gran capacidad de gestión comercial para unirse a nuestro equipo. El rol principal será levantar pedidos en la zona asignada.¿Que vas a ofrecer/vender? Productos de Limpieza y papelería (jabones líquidos, en polvo, suavizantes, detergentes, papel higienico, Servilletas de papel, toallas de papel, bobinas ) Alimentos (derivados de pollo, pescado y cerdo, lacteos)Objetivos: Ampliar la cartera de clientes.Requisitos Monotributista (Colaborador) Experiencia previa en ventas, preferentemente en rubros como limpieza, papelería o alimentos. Excelentes habilidades de comunicación y negociación. Capacidad para trabajar de forma autónoma y organizada.', 0, 'Córdoba, Córdoba', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 16:56:14', '13-04-2026 16:56:14', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179460.html', '2026-04-14T07:05:54.891448');
