INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225128, 13335886, 'Coordinación Administrativa de Consultorios Externos', 'Sanatorio Solano Insitituto Medico Modelo', 'En Sanatorio Solano nos encontramos en la búsqueda de un/a Coordinador/a Administrativo/a de Consultorios Externos, para sumarse a nuestro equipo de Gestión de Pacientes. Misión del puesto: Supervisar la correcta gestión de la atención de pacientes, organizando y controlando los procesos administrativos a su cargo, promoviendo el cumplimiento de los estándares de calidad en la atención. Responsabilidades principales: Coordinar y supervisar al equipo administrativo de Consultorios Externos. Organizar agendas y grillas mensuales de atención profesional. Controlar y rendir los bonos para su correcta facturación. Capacitar al equipo y acompañar el proceso de inducción de nuevos colaboradores. Gestionar reclamos, agradecimientos y sugerencias de pacientes, manteniendo una comunicación empática y efectiva. Elaborar informes mensuales para la jefatura.Requisitos: Tecnicatura en Gestión de Pacientes o carreras afines. Conocimientos en Excel, Geclisa, terminología médica y facturación de prestaciones. Experiencia previa en coordinación o liderazgo de equipos administrativos en salud. Habilidades destacadas de liderazgo, comunicación, empatía y orientación al paciente.', 0, 'San Francisco Solano, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:09:53', '09-04-2026 15:20:50', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 2585, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13335886_bum_v4c8845aa.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225128.html', '2026-04-14T07:05:54.893785');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1117719091, 1478000, '1183CC CONSULTOR/A PAYROLL - Belgrano', 'CONA CONSULTORES EN RRHH', 'En CONA estamos en búsqueda de un/a CONSULTOR/A de PAYROLL para sumarse al equipo de Nóminas.Pensamos en una persona con más de 4 años de experiencia en procesos completos de liquidaciones de multiconvenios, incluido control de Ganancias, libro de sueldo digital (F931), Sicore, boletas sindicales, etc.Buscamos que sea extrovertido/a, con facilidad de expresión y buen manejo de las relaciones interpersonales, para unirse a un equipo de trabajo con identicas características.Tareas principales:-Llevar a cabo el proceso integral de liquidación de sueldos multiconvenio.-Aplicar conocimientos específicos de liquidación de haberes (convenios colectivos, normativa legal).-Realizar el armado de liquidación de sindicatos.-Desarrollar informes de gestión.-Brindar respuesta a las consultas del personal asociado y clientes en materia de liquidación y administración de personal.Requisitos indispensables: Estudiantes y/o Recibido de Contador Público o Administración de Empresas, Recursos Humanos o afines Experiencia previa mínima 4 años. Preferentemente en el rubro de Consultoría/Shared Service/Estudio contable, con experiencia en el manejo del Payroll de más de un cliente interno o externo Avanzado nivel de Excel y manejo de sistema de gestión para liquidación de sueldos. Orientación al cliente Capacidad para trabajar en equipo.Se ofrece:- Puesto efectivo, directo con CONA Consultores- Jornada: Lunes a viernes 9 horas diarias.- Modalidad de trabajo híbrida ( 2 veces en las oficinas y 3 veces home office)- Ubicación: Belgrano, CABA.CUIDATE DE LOS AVISOS LABORALES FALSOSEn CONA siempre postularas por Plataformas de Empleo Directas NO a personas individuales.En CONA Nunca te Pediremos que Envies Foto del DNI ni Documentacion Personal.Búsqueda Laboral EquitativaEl empleador solo podrá solicitarle la información estrictamente necesaria para el desempeño en el trabajo que se ofrece. Ley 6471-21 GCBA', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '13-04-2026', '13-04-2026 11:50:14', '13-04-2026 14:25:13', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 17, 2637, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_1478000_bum_vcc157e48.jpg', 0, 0, 3.13, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1117719091.html', '2026-04-14T07:05:54.893885');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223970, 13510815, 'Jefe de Administración y Contabilidad', 'Il Molino', 'Jefe de Administración y ContabilidadResumen del PuestoBuscamos un profesional con experiencia en Administración y Contabilidad para liderar un equipo y optimizar procesos. El rol requiere un enfoque en control, estrategia y sistematización, con una sólida comprensión de las operaciones financieras y administrativas.Responsabilidades Principales Asegurar la correcta y oportuna ejecución de los cierres contables mensuales. Gestionar la liquidación de sueldos y jornales, incluyendo el cálculo de cargas sociales y la presentación de las declaraciones correspondientes. Supervisar y dirigir el departamento de Administración y Contabilidad. Verificar documentación, circuitos administrativos y registros, identificando desviaciones y proponiendo acciones correctivas. Realizar conciliaciones bancarias y de cuentas contables. Elaborar balances y reportes de costos de producción. Asegurar el cumplimiento de la normativa aplicable y la correcta declaración de impuestos.Requisitos Título de Contador Público con matrícula activa. Experiencia mínima de 3 a 5 años en roles de supervisión, control o gestión administrativa. Experiencia comprobable en liquidación de sueldos. Dominio de herramientas informáticas, incluyendo Excel avanzado y sistemas administrativos. Capacidad para trabajar de forma presencial. Habilidades de liderazgo, planificación y organización. Excelentes capacidades analíticas y de resolución de problemas.', 0, 'Córdoba, Córdoba', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:02:35', '09-04-2026 15:02:35', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 58, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13510815_bum_v107d314b.jpg', NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223970.html', '2026-04-14T07:05:54.893974');
