ULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 14, 30, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118228769.html', '2026-04-14T07:05:54.894394');
