INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179454, 626656, 'Comunnity Manager / Produccion y Edición de Contenido', 'WHITE BAHAMAS', 'El grupo BAHAMA COLORS esta buscando cubrir 3 posiciones PART TIME para sus empresas WHITE BAHAMAS, AMAPOLANN y Estudio SOHEM... Zona: Nuñez, CABA. . . Posición 1 : _ _ Community Manager_ _ PART TIME. Ideal Estudiante de Publicidad, Comunity Manager, Relaciones Públicas, Redacción / similaresBuscamos un perfil que pueda ayudar a la empresa a mejorar su posicionamiento. Incluye agenda de contenidos / creación de contenido para productos de alta gama...Posición 2 : _ _ Content Creator / Producción de contenido _ _ PARTE TIME.Ideal para estudiante de Diseño, imagen y sonido, cine, arte, con habilidades de manejo de cámara. . .Posición 3 : _ _ Editor de Fotos y Videos _ _ PART TIME. Se requiere trabajar con Cupcut, Photoshop y Premier. .. Para cualquiera de estas posisiones enviar CV con: - Foto perfil. - Pretenciones económicas para un trabajo Part Time. -Horarios disponibles para trabajar part time.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Part-time', '12-04-2026', '12-04-2026 15:34:21', '13-04-2026 14:08:53', '2026-04-12', NULL, NULL, '2026-04-12T00:00:00-03:00', NULL, NULL, 1, 0, 18, 80, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_626656_bum_v40abaeb7.jpg', 0, 0, NULL, 40, 'Avisos Gold', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179454.html', '2026-04-14T07:05:54.894518');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227288, 3530, 'Analista Adm. contratos y presupuestos-Exclusivo personas con discapacidad', 'COCA-COLA FEMSA DE ARGENTINA', 'Somos el embotellador más grande del mundo por volumen de ventas. Producimos y distribuimos bebidas de las marcas registradas de The Coca-Cola Company, ofreciendo un amplio portafolio de 134 marcas a más de 270 millones de consumidores cada día.Con más de 97 mil empleados, comercializamos y vendemos aproximadamente mil millones de cajas unidad a través de más de 2 millones de puntos de venta al año. Operando 56 plantas de manufactura y 249 centros de distribución, ubicados en 10 países: México, Argentina, Brasil, Uruguay, Nicaragua, Guatemala, Panamá, Costa Rica, Colombia y Venezuela. Estamos comprometidos en generar valor económico, social y ambiental para todos nuestros grupos de interés en toda la cadena de valor.Nuestra gente impulsa nuestro éxito. Es por ello que somos el embotellador líder de las marcas de Coca-Cola en el mundo, comercializando más de millones de cajas unidad por año. En Argentina operamos en CABA y una extensa porción de GBA y en Uruguay en Montevideo y resto de las ciudades. Somos los responsables de embotellar, comercializar y distribuir los productos de la Compañía Coca-Cola, dentro de ese territorio.En Coca-Cola FEMSA la diversidad, la equidad y la inclusión son la base de la innovación, transversalidad del negocio y el crecimiento sostenible. Trabajamos por reflejar y respetar la riqueza de identidades, perspectivas y talentos únicos que existen en cada lugar. Ofrecemos igualdad de oportunidades a todas las personas que deseen formar parte de nuestro equipo, sin distinción de edad, origen étnico o geográfico, color de piel, nacionalidad, religión o creencias, situación social, condición de discapacidad, estado civil, orientación sexual, identidad o expresión de género. Promovemos procesos de atracción y selección libres de discriminación y sesgos, basados en el talento, la experiencia y el potencial de cada persona. Si necesitas ajustes razonables o apoyos de accesibilidad durante el proceso, por favor compartilo con el equipo de Atracción de Talento. Queremos que tu experiencia con nosotros sea extraordinaria. ¡Te invitamos a sumarte a Coca-Cola FEMSA Argentina buscamos un/a Analista Administrativo/a de contratos, presupuestos y activos- Contrato Eventualbúsqueda exclusiva para personas con discapacidad para ser parte de este desafío! ¿Queres trabajar en un equipo de personas apasionadas por el negocio? Si es así, ¡Coca-Cola FEMSA es el lugar para vos! Estamos buscando un/a Analista Administrativo/a de contratos, presupuestos y activos para unirse a nuestro equipo, bajo un contrato eventual. En este rol, serás responsable de brindar soporte analítico y operativo en la gestión de presupuestos, contratos, descuentos y activos, garantizando la correcta ejecución y registración de las operaciones. Si sos una persona que se anima a proponer nuevas ideas, te emocionan los desafíos y queres ser protagonista de tu desarrollo en una compañía que te impulsa a dar el máximo ¡te invitamos a postularte! ¿Qué valoramos de vos para refrescar el mundo? Capacidad de análisis, organización y foco en el detalle Habilidad para trabajar en equipo y de comunicación Manejo numérico ¿Cómo podés contribuir a crear experiencias? Gestión de contratos y presupuestos: Brindar apoyo en el control de gastos y documentos legales de la empresa. Control de descuentos: Revisar que los descuentos a clientes se apliquen correctamente y pedir la creación de Notas de Crédito cuando corresponda. Registro de facturas: Cargar y controlar facturas relacionadas con publicidad y promociones. Control de materiales: Seguir de cerca el movimiento de activos como pallets y envases. Atención interna: Resolver dudas de las áreas de Ventas, Finanzas y Marketing. Colaborar en el análisis y armado de informes. Requisitos: ¿Qué necesitamos de vos para ser parte de esta aventura?: Formación académica: estudiantes avanzados o graduados de las carreras de Administración, Contador Público, Economía o afines. Experiencia: de 1 a 3 años en posiciones similares (NO excluyente) Dominio de herramientas informáticas: manejo intermedio de Excel (formulas, tablas dinámicas, bases de datos) y PowerPoint. Si sabés usar SAP, Power BI es un plus. Zonas de Trabajo: Nueva Pompeya -CABA Disponibilidad para trabajar de lunes a viernes. Horarios: Flex Hibrido. Idiomas: inglés nivel intermedio (no excluyente) Modalidad de contratación: Eventual Beneficios ¿Cuál es nuestra propuesta?: Coca-Cola FEMSA te brinda una excelente oportunidad para emprender tu carrera profesional, aprender y colaborar con un equipo de personas apasionadas por nuestro negocio. Sé protagonista de tu desarrollo en un ambiente diverso, dinámico y altamente desafiante. Si considerás que necesitás algún ajuste razonable para participar en el proceso de selección, no dudes en informarlo en tu postulación. Pedir un ajuste permite que el proceso sea más accesible e inclusivo para todas las personas. Te ofrecemos un paquete de beneficios que te permitirá desarrollar tu carrera profesional, crecer como persona y disfrutar de tu tiempo libre. Flex Time Program, para favorecer un balance saludable entre tu vida profesional y personal. Descuentos en universidades, contribuyendo a seguir formándote profesionalmente. Clases de inglés en Nulinga, para perfeccionar tu idioma. Productos de la compañía, para que puedas disfrutar de nuestros productos. ️‍️Gimnasio en nuestras instalaciones, para potenciar tu bienestar. Medicina prepaga para vos y tu grupo familiar, promoviendo el cuidado de tu salud. Comedor en planta, para que puedas alimentarte de forma saludable. ¿Queres saber más? ¡Postúlate ya! #SomosCoca-Cola FEMSA #MeSientoBien… Somos la compañía líder en Latinoamérica en el mercado de bebidas, el mayor embotellador de productos Coca-Cola en términos de ventas, representando 1 de cada 10 productos Coca-Cola vendidos en el mundo. Tenemos presencia en 10 países y ya somos más de colaboradores en toda la región. En Coca-Cola FEMSA la diversidad, la equidad y la inclusión son la base de la innovación, transversalidad del negocio y el crecimiento sostenible. Trabajamos por reflejar y respetar la riqueza de identidades, perspectivas y talentos únicos que existen en cada lugar. Ofrecemos igualdad de oportunidades a todas las personas que deseen formar parte de nuestro equipo, sin distinción de edad, origen étnico o geográfico, color de piel, nacionalidad, religión o creencias, situación social, condición de discapacidad, estado civil, orientación sexual, identidad o expresión de género. Promovemos procesos de atracción y selección libres de discriminación y sesgos, basados en el talento, la experiencia y el potencial de cada persona.', 0, 'Buenos Aires, Buenos Aires', 'Híbrido', 'Full-time', '10-04-2026', '10-04-2026 16:02:45', '10-04-2026 16:02:46', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 1, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_3530_bum_v2c1ea9cd.jpg', 1, 1, 4.31, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227288.html', '2026-04-14T07:05:54.894832');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226646, 10202110, 'Operario tareas generales- CONTRATO A PLAZO FIJO DE 6 A 8 MESES', 'RH Talentum', 'Para planta química productiva de la zona de Dock Sud, Avellaneda, nos encontramos en busca de un OPERARIO DE TAREAS GENERALES.Sus principales funciones serán: Carga y descarga de camiones tipo cisterna; envasar producto en bolsones de 1.000 kg y en tambores; armado de estiba y paletizado. llevar las muestras al Laboratorio; Limpieza de la planta, entre otras.Orientamos la búsqueda a candidatos con gran sentido de responsabilidad; compromiso y proactividad,Serán requisitos: secundario completo; disponibilidad horaria para realizar turnos fijos o rotativos; experiencia mínima de un año en plantas productivas y deseable experiencia en manejo de clark tradicional.Se ofrece contratación directa con la empresa; excelente clima laboral; servicio de trasladao en combi desde la estación de tren de Sarandí y de Avellaneda hacia la empresa y Swiss medical para la persona y grupo familiar.Zona: Dosk Sud, AvellanedaHorarios: Lunes a Sábados de 06 a 14 /14 a 22 / 22 a 06 hs, contar con disponibilidad para turnos rotativos. CONTRATO POR PLAZO DE 6 a 8 meses aproximadamente.Esperamos tu postulación!', 0, 'Avellaneda, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 11:31:31', '10-04-2026 11:48:55', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 32, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/0/2/0/2/1/1/0/logoMainPic_10202110.jpg', 1, 0, 3.7, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226646.html', '2026-04-14T07:05:54.894971');
