0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179420.html', '2026-04-14T07:05:54.897373');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229883, 319880, 'Senior Research analyst - Private Credit', 'Randstad Argentina', '¡Esta propuesta te puede interesar! Main Responsibilities: Undertake research and analysis of corporate entities through thorough assessment of the key credit factors, including strengths and weakness to analyze creditworthiness and debt repayment capacity. Understanding the bank''s internal methodology used for credit assessments. Preparing a detailed credit assessment report and elaborately discuss the company profile and credit risk considerations. Assess viability of expansion projects and/or M&A activities using valuation techniques (DCF analysis) to recommend credit alternatives. Prepare / update financial models or financial spreads (including projections) using company filings. Prepare a detailed peer analysis on operating and financial parameters. Should be able to defend his/her views on the counterparty / covered entity when challenged by senior stakeholders. Support senior analysts / project managers on ad hoc requests. Other activities may include preparing industry research reports, maintaining and updating financial models and company/industry specific databases. Experience: 2 years of experience in assessing credit risk or credit research or equity research or financial research of global corporates. Prior experience of 3 years in a similar profile Required Skills: Strong understanding of core finance and accounting concepts. Excellent report writing and communication skills. Ability to communicate analytical thoughts in a crisp, concise and precise manner. Strong inter-personal skills and ability to participate/contribute as a team player. Should be willing to put in the extra hours when tight deadlines need to be met. Professional working proficiency in English and Spanish languages are a must. MINIMUM & PREFERRED EDUCATION Advanced degrees and certifications such as a CFA and Masters in Finance/Economics, MBA are preferred Main Responsibilities: Undertake research and analysis of corporate entities through thorough assessment of the key credit factors, including strengths and weakness to analyze creditworthiness and debt repayment capacity. Understanding the bank''s internal methodology used for credit assessments. Preparing a detailed credit assessment report and elaborately discuss the company profile and credit risk considerations. Assess viability of expansion projects and/or M&A activities using valuation techniques (DCF analysis) to recommend credit alternatives. Prepare / update financial models or financial spreads (including projections) using company filings. Prepare a detailed peer analysis on operating and financial parameters. Should be able to defend his/her views on the counterparty / covered entity when challenged by senior stakeholders. Support senior analysts / project managers on ad hoc requests. Other activities may include preparing industry research reports, maintaining and updating financial models and company/industry specific databases. Experience: 2 years of experience in assessing credit risk or credit research or equity research or financial research of global corporates. Prior experience of 3 years in a similar profile Required Skills: Strong understanding of core finance and accounting concepts. Excellent report writing and communication skills. Ability to communicate analytical thoughts in a crisp, concise and precise manner. Strong inter-personal skills and ability to participate/contribute as a team player. Should be willing to put in the extra hours when tight deadlines need to be met. Professional working proficiency in English and Spanish languages are a must. MINIMUM & PREFERRED EDUCATION Advanced degrees and certifications such as a CFA and Masters in Finance/Economics, MBA are preferred Si consideras que reunís los requisitos para el puesto y te gustan los desafíos, no lo dudes…. ¡Postulate! Sobre Randstad En Randstad nos moviliza ayudar a las personas y a las organizaciones a desarrollar todo su potencial. Ese es el compromiso que asumimos como compañía en todo el mundo, un compromiso que nos impulsa a ir más allá para lograr que nuestros clientes y candidatos alcancen el éxito. ¿Cómo lo hacemos?, combinando nuestra pasión por las personas con el poder de la tecnología, creando experiencias más humanas, que nos permitan ser una fuente de inspiración y apoyo para quienes nos eligen. Porque estamos convencidos de que mejores personas hacen mejores.', 0, 'Vicente López, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 17:10:57', '14-04-2026 04:07:14', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 1, 25, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_319880_bum_vff58225f.jpg', 1, 0, 4.28, 70, 'Simples', 'bumeran', 'simple', 1, 0, 1, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229883.html', '2026-04-14T07:05:54.897627');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227404, 13098238, 'EJECUTIVO DE CUENTAS', 'MK Consultores', 'Importante Empresaindustrial grafica, ubicada en GBA, incorporara a su equipo comercial un EJECUTIVO DE CUENTAS.La búsqueda se orienta a profesionales con marcado perfil comercial, orientación al logro de objetivos, proactividad, capacidad de trabajo en equipo, y orientación al cliente y a la calidad de gestión.Sus principales tareas serán: Gestionar y realizar el seguimiento de la cartera de clientes. Capturar nuevos clientes con potencial de negocios y crecimiento. Realizar estudio de mercado. Realizar el seguimiento del vínculo comercial. Asesoramiento personalizado, cotizaciones especiales y resolución de reclamos de clientes. Participar de reuniones empresariales con el cliente interno y externo. Manejo de CRM.Requisitos: Preferentemente profesionales con estudios terciarios/ universitarios orientados a Comercialización, Administración de Empresas, MKT o afines. Experiencia mínima de 5 años en puestos comerciales Excelentes habilidades de comunicación, negociación e interrelación.Los interesados deberán enviar su CV indicando remuneración pretendida.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 16:56:20', '10-04-2026 16:56:20', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, NULL, 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227404.html', '2026-04-14T07:05:54.897716');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223540, 13235250, 'Ejecutivo de cuentas', 'Zimmer aberturas', 'Nos encontramos en la búsqueda de ejecutivos de cuentas o afines, para asistir y dar soporte fábrica de aberturas de PVC. Funciones y Responsabilidades: - Venta de aberturas en área de construcción para grandes proyectos - Soporte a oficina técnica para cotizar- Visitas a obras Requisitos: - Poseer experiencia en posiciones similares- Se valorará movilidad propia - Buscamos a alguien proactivo con facilidad para trabajar en equipo, organizado y metódico - Residir en Buenos Aires o CABA - Disponibilidad full time - Trabajo de Lunes a Viernes de 8:00 a 17:00hs La Remuneración pretendida estará compuesto por un básico y comisiones', 0, 'General Rodríguez, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 13:51:21', '13-04-2026 12:27:18', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, NULL, 0, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223540.html', '2026-04-14T07:05:54.897794');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229704, 2048010, 'Analista de Cuentas a Pagar(Martinez)', 'SM Recursos Humanos', 'SM se encuentra en la busqueda de un Analista de Cuentas a Pagar para reconocida empresa del rubro del Palstico,LIDER,en el rubro.La busqueda la dirigimos a jovenes de las Carreras de Ciencias Economicas con experiencia en el puesto. Es importante poseer Ética y Sencillez. Empatia. Buenas relaciones interpersonales.Trabajo en equipo y colaboracion. Pensamiento Analitico y Conceptual. Iniciativa y autonomia. Compromiso con la Calidad del Trabajo.TAREAS DEL PUESTO:*Recepción y Organización de Documentos y comprobantes de Gastos.*Control y Registración de Documentos y comprobantes de Gastos.*Verifica Vencimientos y Montos de los Comprobantes para Cancelar Pasivos de la Compañía.*Atención telefónica, por correo electrónico y personalizado de proveedores.*Conciliación de Cuentas Corrientes de Proveedores y Cuentas Contables del Sector.*Alta y Actualización de Legajos de Proveedores.*Archivo de la Documentación del Sector.CONOCIMIENTOS ESPECÍFICOS:* Excel nivel avanzado* Paquete Office* Inglés Básico* Sistema de Gestión Tango (no excluyente)CONDICIONESEdad: 25-35 años.Sexo: Indistinto.Estudios. Carreras de Ciencias Economicas,Administracion .Jornada Laboral: Lunes a Viernes de 9 hs a 18 hs.1 dia HO.Puesto: Efectivo.incorporacion Inmediata y Directa.Obra : Galeno Plan Azul(Para el grupo fliar)Muy buenas condiciones de Contratacion.', 0, 'Martínez, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 15:56:55', '13-04-2026 15:56:55', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 1, 2592, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2048010_bum_v6176e4fd.jpg', 1, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229704.html', '2026-04-14T07:05:54.897874');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224021, NULL, 'Analista de Cuentas corrientes de clientes', 'Confidencial', 'EMPLEADA PARA CUENTAS CORRIENTES en EMPRESA RUBRO ALIMENTICIO EN PILARLa Empresa se encuentra en la búsqueda de una persona de sexo femenino, para ocupar el puesto de Analista de Cuentas Corriente de Clientes y otras tareas administrativas afines del sector.La contratación es directa de la Empresa Argentina líder del rubro alimenticio, con 35 años de trayectoria.Ubicada en el Parque Industrial de Pilar, con distribución en todo el país, a través de distribuidores y Cadenas de supermercadosRequisitos: Mujer mayor de 24 años. Experiencia en tareas relacionadas con análisis de cuentas corrientes de Deudores en general y en particular sería conveniente, no excluyente, experiencia con cuentas de Cadenas de supermercados y distribuidores y en Administración en general, Manejo de Word, Excel, y programas de gestión. Disponibilidad: full time (9 hs) de lunes a Viernes 9 a 18 horas Residencia: Partido de Pilar o alrededores ( EXCLUYENTE)Perfil solicitado: Capacidad de aprendizaje y voluntad para cumplir objetivos. Capacidad de resolución de problemas. Proactividad Buenas relaciones interpersonales. Predisposición para Trabajo en equipo.Tareas que tendrá a su cargo:Control de los pagos de clientes.Interacción con el resto de los sectores de la empresa.Carga de comprobantes en el portal del cliente.Eventualmente tareas de Facturación en el sistema propio de la empresa, como reemplazo del personal del sector en alguna oportunidad (tarea a realizar previa capacitación de la empresa).Tareas de colaboración con la Administración de ventas y logística. Archivo de documentación, pases al sistema de diversos documentos. Controles de documentación general.Se tiene previsto realizar la Incorporación inmediata a la empresa.Referir REMUNERACION PRETENDIDA en su Currículum vitae.', 1, 'Pilar, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 17:11:41', '08-04-2026 17:11:41', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 1, 2592, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224021.html', '2026-04-14T07:05:54.897962');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118230527, 319880, 'Especialista de Cuenta (RR.HH) - Plazo Fijo', 'Randstad Argentina', '¡Esta propuesta te puede interesar! MISIÓN DEL PUESTO En Randstad buscamos sumar un/a Especialista de Cuenta que tenga como principal responsabilidad garantizar la excelencia en la ejecución de los procesos de trabajo de cara a nuestro cliente. PRINCIPALES RESPONSABILIDADES Desarrollar una relación duradera con el cliente convirtiéndolo en un partner. Resalta al cliente constantemente el valor agregado de nuestro concepto. Participa en reuniones de planificación Reclutamiento y selección de procesos masivos (perfiles operativos). Mantiene informados al cliente y a los colaboradores acerca de los procedimientos administrativos a seguir. Ejecuta el plan de acción para el cliente en cooperación estrecha con el PM. Acompaña a los colaboradores del cliente en la operación diaria. Ejecuta las tareas administrativas relativas al cliente y a los trabajadores. Brindar apoyo en la liquidación de sueldos. REQUISITOS EXCLUYENTES Técnicos o licenciados de carreras afines (Administración de Empresas, Recursos Humanos, Psicología, etc.). Experiencia en procesos de selección y reclutamiento masivo (excluyente). Experiencia en gestión de nómina y liquidación de sueldos. Experiencia en gestión y contacto con colaboradores. Movilidad propia (excluyente). Actitud proactiva, orientado a resultados, vocación al servicio y adaptación a los cambios. INFORMACIÓN ADICIONAL Contrato: Plazo fijo con posibilidades de continuación. Jornada laboral: Lunes a jueves de 8 a 17 y viernes de 8 a 16 hs. Modalidad: Híbrida 3x2 (tres días presenciales en oficinas/planta de cliente y dos días remotos). Ubicación: Venado Tuerto, Santa Fe. Si consideras que reunís los requisitos para el puesto y te gustan los desafíos, no lo dudes…. ¡Postulate! Sobre Randstad En Randstad nos moviliza ayudar a las personas y a las organizaciones a desarrollar todo su potencial. Ese es el compromiso que asumimos como compañía en todo el mundo, un compromiso que nos impulsa a ir más allá para lograr que nuestros clientes y candidatos alcancen el éxito. ¿Cómo lo hacemos?, combinando nuestra pasión por las personas con el poder de la tecnología, creando experiencias más humanas, que nos permitan ser una fuente de inspiración y apoyo para quienes nos eligen. Porque estamos convencidos de que mejores personas hacen mejores.', 0, 'Venado Tuerto, Santa Fe', 'Presencial', 'Full-time', '14-04-2026', '14-04-2026 06:27:54', '14-04-2026 06:45:32', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 17, 48, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_319880_bum_vff58225f.jpg', 1, 0, 4.28, 70, 'Simples', 'bumeran', 'simple', 1, 0, 1, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118230527.html', '2026-04-14T07:05:54.898079');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227348, 13110602, 'Analista de Facturación y Cuenta Corriente - copia', 'Bumeran Selecta', 'Empresa lider con 50 años de experiencia en Diseño y soluciones al servicio del cuidado de los sistemas dedesagües. Nos encontramos en la búsqueda de un Analista de Facturación y Cuenta Corriente, orientado al detalle y la organización, para incorporarse al equipo administrativo. Buscamos una persona con experiencia sólida en entornos de alto volumen de facturación, capaz de gestionar procesos con precisión y compromiso. Requisitos: Emitir facturación a través del sistema ROM (similar a Tango u otros sistemas de gestión). Generar facturas sobre los servicios brindados. Realizar análisis de cuentas corrientes de clientes. Elaborar informes de gestión vinculados al área. Experiencia previa mínima de 3 años en emisión de facturas mediante sistemas de gestión (excluyente). Se valorará experiencia en empresas con alto volumen de comprobantes emitidos. Manejo de Excel intermedio/avanzado. Sexo: Masculino Edad: Mayores de 40 años Nivel de estudios: Secundario completo Modalidad: 100% presencial Lugar de trabajo: Olivos, Buenos Aires Horario: Lunes a viernes de 8:30 a 17:30 hs o de 9:00 a 18:00 hs (1 hora de almuerzo)Valoramos perfiles proactivos, responsables y con orientación al detalle. Sábados: de 8:00 a 13:00 hs Beneficios Estabilidad Laboral.Puesto en Convenio.', 0, 'Olivos, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 16:32:31', '10-04-2026 16:32:31', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 2643, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13110602_bum_vab9a2cbb.jpg', 1, 0, 3.7, 10, 'Home', 'bumeran', 'home', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227348.html', '2026-04-14T07:05:54.898158');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224094, 406710, 'Ejecutivo de cuentas multicanal - Zona Cuyo', 'Ledesma', 'Somos una empresa agroindustrial Argentina con más de 100 años de historia, líder en la producción de azúcar y papel, y con una importante participación en los mercados de frutas y jugos cítricos, alcohol, bioetanol, carne y cereales. Empleamos a cerca de personas que en su mayoría trabajan en Jujuy, provincia en la que nació Ledesma y donde tenemos hectáreas destinadas a la cosecha de nuestra principal materia prima: la caña de azúcar. Este cultivo se renueva anualmente y se aprovecha por completo. Producimos con la mejor calidad, preservamos los ecosistemas que nos rodean y cuidamos el bienestar de nuestros colaboradores y de las comunidades donde estamos presentes. Para la Gerencia Comercial de nuestra Dirección Negocio Azúcar, nos encontramos en búsqueda de un/a Ejecutivo de cuentas para trabajar en región Cuyo. Serán sus principales responsabilidades: Gestionar la atención y desarrollo de la cartera multicanal de clientes actuales y potenciales en Mendoza, San Juan y La Rioja. Llevar adelante la operatoria comercial del canal de ventas. Colaborar con nuevos desafíos del negocio, detectando oportunidades y potenciando la presencia de nuestra marca en las provincias asignadas. Hacer seguimiento de las cuentas corrientes, la operación comercial, distribución y logística de entrega a clientes. Requisitos: Graduado/a o próximo a graduarse de Ingeniería Industrial, Lic. Comercialización o Lic. Administración de empresas (excluyente) Experiencia previa de dos años en roles comerciales, idealmente dentro de consumo masivo. Movilidad propia y disponibilidad para viajar a las zonas mencionadas (excluyente) Residencia en Mendoza (excluyente) Beneficios Prepaga para vos y tu grupo familiar ‍️ Modalidad de trabajo híbrida Días adicionales de vacaciones Viernes Flex de Verano Día de cumpleaños libre Esquema de compensación por viáticos Y mucho más!', 0, 'Mendoza, Mendoza', 'Híbrido', 'Full-time', '10-04-2026', '10-04-2026 15:27:20', '10-04-2026 15:27:20', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_406710_bum_vb92e12bc.jpg', 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224094.html', '2026-04-14T07:05:54.898255');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224991, 13423232, 'Asesor/a Comercial para franquicia Ramos Mejia', 'Cultura RRHH', 'Lic. en Psicología - Selección de Personal - Evaluaciones Psicolaborales - RRHH Somos Pirka, Empresa Líder de Revestimientos con sede en Bs As y franquicias en varias ciudades del país y de la región, e incorporamos un/a Asesor/a Comercial para la franquicia de Ramos Mejia.Si sos una persona proactiva, con gran facilidad para las relaciones interpersonales, que disfruta de asesorar, brindar un servicio de calidad y enes deseos de vender y crecer, este es el puesto para vos.Tareas principales: Asesoramiento comercial y técnico a domicilio (visitas previamente concertadas). Armado de presupuesto y gestión de clientes. Coordinación de órdenes de trabajo con instaladores. Captación de nuevos clientes y cierre de ventas. Participación en reuniones semanales en el local, orientadas al seguimiento de objetivos, análisis de resultados y planificación comercial. Registro y seguimiento de clientes. Requisitos: Vehiculo propio (excluyente) Experiencia en ventas de productos o servicios (telefonía, tarjetas, seguros, créditos financieros, etc.) (deseable). Perfil autónomo, proactivo y orientado a resultados. Destacada capacidad para desarrollar relaciones con clientes, basada en la empatía, la escucha activa y la comprensión de sus necesidades. Orientación a prácticas de venta responsables, priorizando la ética profesional, honestidad y transparencia con foco en generar relaciones de confianza a largo plazo. Pasión por las ventas y el trato con el cliente, con habilidad para identificar oportunidades y concretar cierres efectivos. Buenas habilidades de comunicación y atención personalizada. Capacidad de organización, autogestión y compromiso con el cliente. Manejo de herramientas informáticas (Word, Excel, redes sociales). Beneficios Te vamos a formar y capacitar para que puedas llevar adelante la misión de asesorar y vender nuestros servicios a los clientes, asegurando una experiencia verdaderamente satisfactoria.‍ Sueldo base durante la capacitación. Luego, esquema a comisión sin limites, con altos ingresos comprobables. Viáticos a cargo de la empresa Oportunidades de crecimiento dentro de una marca con sólida trayectoria. Horario: Lunes a viernes + sábados mediodía (según agenda de visitas).Modalidad: 100% presencial¿Estas listo/a?', 0, 'Ramos Mejía, Buenos Aires', 'Presencial', 'Full-time', '14-04-2026', '14-04-2026 05:02:30', '14-04-2026 05:02:30', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224991.html', '2026-04-14T07:05:54.898360');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224776, 13498043, 'Customer Service - Coordinación de Embarques', 'Grupo AMS', 'En Grupo AMS nos encontramos en la búsqueda de un/a Customer Service - Coordinación de Embarques Maritimos para sumarse a nuestro equipo, con foco en la gestión integral de operaciones de comercio internacional.Sus principales responsabilidades serán: Coordinar embarques marítimos de importación y exportación (FCL/LCL) de manera integral (end to end). Realizar el seguimiento de cargas desde origen hasta destino, en contacto con navieras, agentes en origen/destino y proveedores logísticos. Gestionar bookings con navieras y dar seguimiento a los cut off, ETD/ETA y posibles rollovers. Mantener comunicación fluida con clientes, despachantes de aduana y áreas internas. Enviar y revisar cotizaciones marítimas en casos específicos. Instruir a agentes del exterior sobre el manejo operativo de cada embarque. Controlar documentación marítima (HBL, MBL) y coordinar su correcta emisión. Verificar y controlar facturas de agentes, asegurando coherencia con las cotizaciones y condiciones acordadas. Mantener actualizada la información en sistemas y planillas de seguimiento operativo. Armar y mantener ordenadas las carpetas operativas de cada embarque. Asegurar la rentabilidad de las operaciones y control de costos asociados. Detectar oportunidades de mejora en tiempos de tránsito y eficiencia operativa.Requisitos: Experiencia minimo 2 años en posiciones similares en logística internacional. Inglés avanzado. Buen manejo de Excel.Competencias claves: Excelente organización y gestión del tiempo. Capacidad analítica y resolución de problemas. Buen manejo de relaciones interpersonales y trabajo en equipo. Fuerte orientación al cliente y rapidez de respuesta. Comunicación efectiva (oral y escrita). Habilidades de negociación. Capacidad para trabajar bajo presión y gestionar múltiples tareas.Condiciones: Modalidad híbrida | Lunes a viernes de 8:30 a 17:30 Zona: Vicente López (se priorizan perfiles cercanos)', 0, 'Vicente López, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 10:22:28', '13-04-2026 09:20:38', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 2, 100, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13498043_bum_vabb37ace.jpg', NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224776.html', '2026-04-14T07:05:54.898450');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219400, NULL, 'Administrativo/a para Data Entry', 'Confidencial', 'Estamos en la búsqueda de un Administrativo/a para Data Entry, análisis de documentación, etc.Se valora experiencia en el puesto y conocimiento del sistema SAP.Modalidad presencial.Es requisito contar con un amplio manejo de Excel y Office.L a V de 8.30hs a 17.30hs', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 10:22:46', '07-04-2026 10:22:46', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219400.html', '2026-04-14T07:05:54.898510');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227031, 13405546, 'Odontólogo/a General', 'Mouzo Odontologia', 'Odontólogo/a General Resumen del Puesto Buscamos un/a Odontólogo/a General talentoso/a y comprometido/a para unirse a nuestro equipo en constante crecimiento. El candidato ideal será un profesional enfocado en la salud bucal integral y la calidez en el trato al paciente. Responsabilidades Clave Realizar diagnósticos precisos mediante exámenes clínicos y radiografías. Desarrollar y explicar planes de tratamiento integrales a los pacientes. Realizar procedimientos de odontología general (obturaciones, endodoncias básicas, limpiezas, extracciones). Ofrecer tratamientos de estética dental (blanqueamiento, carillas). Mantener registros precisos de los pacientes en el software de la clínica. Requisitos Título de Odontólogo/a o equivalente. Experiencia comprobable en odontología general. Conocimiento en tratamientos de estética dental. Habilidad para realizar diagnósticos y planes de tratamiento. Excelentes habilidades interpersonales y de comunicación con el paciente. Capacidad para trabajar de forma autónoma y colaborativa.', 0, 'Villa Ballester, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 14:15:57', '10-04-2026 14:15:57', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2665, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227031.html', '2026-04-14T07:05:54.898590');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227154, 13181155, 'Administrativo de Deportes - Zona Canning (Ezeiza)', 'IC Consultora', 'Nos encontramos en la búsqueda de un Administrativo de Deportes para incorporarse a una reconocida institución deportiva ubicada en Canning (Ezeiza).La posición está orientada a estudiantes avanzados o graduados del Profesorado de Educación Física, con perfil organizado, proactivo, vocación de servicio y afinidad con el deporte, que puedan brindar soporte integral al área, combinando tareas administrativas, operativas y de atención al socio.Responsabilidades del puesto: Gestionar el control de stock e insumos deportivos, incluyendo ingresos, egresos y seguimiento de inventarios. Atender y asesorar a socios y deportistas, brindando respuesta a consultas y asegurando una experiencia de calidad. Administrar información del área: carga de datos, gestión de inscripciones a actividades, clases y torneos. Elaborar reportes e indicadores básicos del sector utilizando Excel. Coordinar la logística de materiales y espacios para entrenamientos y competencias. Colaborar en la organización de eventos deportivos. Articular con profesores, entrenadores y distintas áreas del club. Brindar soporte en tareas administrativas generales del sector. Requisitos: Estudiante avanzado o graduado del Profesorado de Educación Física (excluyente). Experiencia mínima de 2 años en clubes deportivos, gimnasios o espacios vinculados al deporte (excluyente). Manejo de paquete Office, principalmente Excel. Se requiere un nivel sólido de Excel para la confección de reportes, uso de fórmulas básicas, tablas dinámicas y seguimiento de información. (excluyente). Movilidad propia (excluyente). Residencia en zonas cercanas a Canning / Ezeiza. Disponibilidad para trabajar miércoles a domingos, incluyendo fines de semana y feriados (excluyente). Se valorará manejo de idioma inglés (no excluyente). Orientación al cliente y excelente trato interpersonal. Organización, autonomía y capacidad de gestión. Compromiso, responsabilidad y trabajo en equipo. Capacidad para desenvolverse en entornos dinámicos. Interés genuino por el deporte y las actividades recreativas. Beneficios Jornada laboral de 44 horas semanales. Otoño / Invierno: miércoles a domingos de 8 a 17 hs (un día salida 16 hs). Primavera / Verano: miércoles a domingos de 7 a 16 hs (un día salida 15 hs). Modalidad presencial. Posición bajo convenio. Salario bruto estimado: $ (incluye básico + presentismo). Contratación directa por la empresa. Almuerzo / vianda a cargo de la compañía. Pago adicional por trabajo en feriados (100%) y compensación de horas. Estabilidad laboral en entorno deportivo de primer nivel.Si te interesa formar parte de un entorno dinámico, vinculado al deporte y con contacto permanente con socios, esperamos tu postulación.IC Consultora de RRHHAcompañamos el crecimiento de empresas y personas, generando oportunidades de valor.', 0, 'Canning, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 15:04:33', '10-04-2026 15:04:33', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 22, 31, 1, NULL, 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227154.html', '2026-04-14T07:05:54.898743');
