T07:05:54.899020');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221855, 2073200, 'Encargado de Recepción y Depósito', 'GI GROUP Argentina', 'NosotrosTu futuro, nuestra pasión.Somos una consultora de Recursos Humanos de origen italiano con más de 15 años en el país. Aportamos valor en la selección y tercerización responsable de recursos humanos.Trabajamos con empresas de primera línea, generalmente internacionales, buscando perfiles profesionales, técnicos y de alta gerencia. Proveemos servicios de seleccón, personal eventual y tercerización. Somos #SIMPLES / HUMANOS / EXPERTOSVÁLIDO PARA NUESTROS AVISOS EN CIUDAD DE BUENOS AIRES:Búsqueda laboral equitativa. El empleador solo podrá solicitarle la información estrictamente necesaria para el desempeño en el trabajo que se ofrece (Ley 6471). Para nuestro importante cliente nos encontramos en búsqueda de un Encargado de Recepción y Depósito.Principales responsabilidades:Gestión Operativa de Ingreso y Picking Supervisión y liderazgo del personal, gestión de licencias y matriz de polivalencia. Coordinación de tareas de picking y transferencias, intervención ante desviaciones. Auditoría de recepción: verificación de productos con documentación y reporte de discrepancias. Control de stock: carga y trazabilidad en sistema informático. Logística inversa: coordinación de devoluciones y productos no conformes.Gestión de Almacenamiento e Inventarios Optimización de espacios bajo criterios de eficiencia (Slotting/ABC). Ejecución de inventarios cíclicos y generales, análisis de ajustes y medidas correctivas.Seguridad, Higiene y Mantenimiento Cumplimiento de normas de seguridad e higiene industrial. Supervisión del uso correcto de EPP y dispositivos de seguridad. Monitoreo de herramientas y maquinaria crítica, mantenimiento preventivo. Orden y limpieza bajo metodología 5S.Análisis y Reporte (Nivel Estratégico) Monitoreo de indicadores de gestión (KPIs). Identificación de oportunidades de mejora y participación en nuevas tecnologías. Cumplimiento de procedimientos generales y particulares del sector.Consideraciones Finales Colaborar en otras actividades a pedido del Coordinador/Jefe. Realizar todas las acciones necesarias para el logro de objetivos y metas. Requisitos: Experiencia previa no menor a 2 años en posiciones similares (Excluyente)Formación en carreras de Logística, Gestión Operativa o afines (Excuyente)Experiencia con sistemas logísticos (ERP/WMS/RF)Dominio de ExcelConocimientos de normas de seguridad industrial y gestión de riesgos Competencias:Orientación al detalleLiderazgoPensamiento críticoOrganizaciónGestión del tiempo Beneficios Horario: lunes a viernes de 6hs a 16hs y sábados de 8hs a 13hs.Modalidad: PresencialLugar de trabajo: Zona NortePrepagaCapacitación Posibilidad de desarrollo', 0, 'Villa Maipú, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 15:49:28', '08-04-2026 09:42:18', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 3, 2638, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2073200_bum_v6d4c351c.jpg', 1, 0, 3.14, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221855.html', '2026-04-14T07:05:54.899124');
