INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179128, NULL, 'ABOGADO INTEGRAL ESPECIALISTA EN DERECHO EMPRESARIO', 'Confidencial', 'Buscamos incorporar un/a abogado/a semi senior con perfil generalista, orientado al asesoramiento integral de empresas, principalmente PYMES.El rol requiere autonomía, criterio práctico y capacidad para interactuar directamente con clientes, entendiendo el negocio más allá del aspecto estrictamente legal. Responsabilidades principales Asesoramiento legal integral a clientes (societario, contractual y laboral) Gestión y seguimiento de temas laborales (consultas, conflictos, desvinculaciones, estrategia preventiva) Redacción y revisión de contratos comerciales y documentación societaria Atención directa a clientes y participación en reuniones Coordinación con estudios externos (contables, litigios, etc.) Identificación de riesgos legales y propuesta de soluciones prácticas Requisitos Abogado/a graduado/a Experiencia de 6 a 10 años en estudios jurídicos o asesoramiento a empresas Experiencia comprobable en derecho laboral (excluyente) Experiencia en asesoramiento a PYMES (muy valorado) Perfil generalista (no hiper especializado) Buen manejo de redacción jurídica y comunicación con clientes Proactividad, autonomía y criterio práctico Se valorará Experiencia en derecho societario y contractual Conocimiento del entorno regulatorio argentino Capacidad de priorización y manejo de múltiples temas en simultáneo Interés en el negocio del cliente (visión “abogado de empresa”)Qué ofrecemos Trabajo con clientes dinámicos y en crecimiento Exposición directa a clientes y toma de decisiones Buen clima de trabajo y equipo profesional Posibilidades de desarrollo y crecimiento', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 10:56:07', '13-04-2026 10:16:52', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 13, 28, 1, NULL, NULL, NULL, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179128.html', '2026-04-14T07:05:54.899269');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229723, 10108477, 'Analista SSR Programador - Java React', 'María de la Paz Sarmiento', 'Empresa líder en el mercado de la salud, que promueve la diversidad cultural, comprometiénose en brindar un ambiente inclusivo y colaborativo a su gente, donde puedas potenciar tus habilidades siendo vos mismo, co- creando un espacio de constantes oportunidades de icrecimiento. Buscamos sumar a Desarrollador Full Stack Semi Senior (Java & React), para la Dirección de Sistemas y Tecnología de la compañía.Misión del Rol: Contribuir al desarrollo de nuevas funcionalidades y proyectos (Full Stack) de la Oficina Virtual, asegurando la calidad técnica y la rápida resolución de incidentes, con un alto nivel de autonomía y adherencia a las buenas prácticas de equipo. Responsabilidades Diseñar, desarrollar y mantener APIs REST robustas y escalables utilizando Spring Boot. Construir interfaces de usuario modernas, dinámicas y responsivas con Colaborar estrechamente con perfiles funcionales y otros desarrolladores en un entorno ágil (Scrum/Kanban). Escribir código limpio, mantenible y bien documentado, participando activamente en revisiones de código (Code Reviews). Diagnosticar y solucionar problemas técnicos, asegurando la calidad y el rendimiento de las aplicaciones. Lunes a Jueves de 9 a 18 hs; Viernes de 9 a 17 hs, CABA – Modalidad de Presencialidad hibrida4x1 (residentes CABA/GBA) / 100% remoto (residentes fuera de Buenos Aires) Sumate a una compañía que trabaja todos los días para que millones de personas vivan más y mejor. Requisitos: Backend (Java): Experiencia mínima de 3 años en desarrollo de software, con un foco claro en el ecosistema Java. Sólidos conocimientos y experiencia práctica con Spring Boot ( para la creación de microservicios o APIs REST. Experiencia con Java 15. Si has trabajado con Java 8 en proyectos anteriores, también es valorable. Frontend (React): Al menos 2 años de experiencia desarrollando con Dominio de componentes funcionales y Hooks (useState, useEffect, useContext). Experiencia en la gestión de estado de la aplicación (usando Context API, Reducers o Redux). Bases de Datos: Excelente dominio de SQL. Capacidad para escribir y depurar consultas complejas (JOINs, agregaciones) y entender el uso de Vistas y Stored Procedures. Herramientas y Calidad: Experiencia comprobable con GIT y flujos de trabajo basados en Pull Requests. Se valorará muy positivamente la experiencia en testing unitario y de integración (JUnit, Mockito). Habilidades Blandas: Alta capacidad de autonomía y proactividad. Excelentes habilidades de comunicación y trabajo en equipo. Mentalidad de resolución de problemas y atención al detalle. Inteligencia Artificial: Conocimiento básico/intermedio en uso de IA para automatización y optimización de procesos, manejo de prompts y herramientas de IA actuales Beneficios Beneficios Gran oportunidad de desarrollo.‍️ Prepaga para vos y tu grupo familiar️Días adicionales de vacaciones.‍ Beneficio de pago de Conectividad Horario flexible y esquema híbrido de trabajo Licencias Udemy para que puedas capacitarte en lo que quieras.Acceso preferencial en la contratación de productos y/o servicios como seguros de caución, hogar, automotor, retiro, vida y ahorro.Campaña de vacunación gratuita️‍️️‍️ Cobertura en Gimnasios a través de la red WellhubDescuentos corporativos en cines, teatros, viajes, restaurantes, spas y otros rubros.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '13-04-2026', '13-04-2026 16:09:43', '13-04-2026 16:09:43', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 19, 34, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229723.html', '2026-04-14T07:05:54.899404');
