INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224522, 10221578, 'Líder Comercial Industrial – Neuquén | Desarrollo de Negocio', 'SPEEDWORK RRHH', 'Líder Comercial Industrial – Neuquén | Desarrollo de Negocio📍 Neuquén | Posibilidad de Modalidad híbrida💼 Sobre la oportunidadImportante compañía en expansión, vinculada a soluciones industriales y comercialización de productos técnicos, incorpora un/a Líder Comercial Industrial para liderar su operación en Neuquén.Buscamos un perfil con fuerte impronta comercial y presencia en campo, capaz de desarrollar negocio, generar oportunidades y liderar equipo en uno de los mercados más dinámicos del país: Oil & Gas.🎯 ¿Cuál será tu desafío? Liderar la operación comercial en la región Desarrollar nuevos clientes y expandir la cartera actual. Generar oportunidades de negocio en entornos industriales y técnicos. Participar en procesos de venta consultiva:Relevamiento de necesidades Cotizaciones Licitaciones Analizar el mercado y detectar oportunidades de crecimiento. Liderar y potenciar el equipo comercial local. (2 vendedores a cargo) Representar a la compañía frente a clientes estratégicos.👤 ¿Qué buscamos? Experiencia en ventas B2B de productos industriales Oil y Gas o soluciones técnicas para el sector o afines. Trayectoria en industrias como Oil & Gas, energía o afines. Perfil comercial con capacidad de negociación en entornos técnicos. Experiencia liderando equipos. Formación técnica (Ingeniería o similar) o sólida experiencia equivalente. Inglés escrito (excluyente). Perfil autónomo, proactivo y orientado a resultados.⭐ Valoramos especialmente Experiencia en ventas de campo (no rol de escritorio). Capacidad de generar negocio desde cero (hunter). Habilidad para interactuar con perfiles técnicos (ingenieros, operaciones, etc.). Orientación a objetivos y crecimiento.💰 ¿Qué te ofrecemos? ✅ Puesto efectivo 💵 Sueldo fijo + esquema de comisiones 🍽️ Almuerzo cubierto 🏥 Prepaga OSDE 🚗 Gastos de viáticos cubiertos 💪 Beneficios de gimnasio 🎂 Día libre por cumpleaños 🏡 Posibilidad de esquema híbrido 📈 Oportunidad de liderar y desarrollar una operación con alto potencial de crecimiento📩 PostulateSi te motiva el desafío de liderar, desarrollar negocio y crecer en una industria clave, queremos conocerte.', 0, 'Neuquén, Neuquén', 'Híbrido', 'Full-time', '08-04-2026', '08-04-2026 21:01:37', '08-04-2026 21:01:37', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 6, 2628, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10221578_bum_v4a20533f.jpg', 1, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224522.html', '2026-04-14T07:05:54.899675');
